mapper.select:
select id, type, version, status, effective_at, created_at, updated_at from cm_legal_documents
and type = #{type}
order by type, effective_at desc, updated_at desc

select id, document_id, locale, title, sections, created_at, updated_at
from cm_legal_document_contents
where document_id = #{documentId}
  and locale = #{locale}
limit 1

mapper.insert:
insert into cm_legal_documents (
    id, type, version, status, effective_at, created_at, updated_at
) values (
    #{id}, #{type}, #{version}, #{status}, #{effectiveAt}, now(), now()
)
